String format(LoggingEvent event) {
    // Ensure that the event is not null
    if (event == null) {
        throw new IllegalArgumentException("The event cannot be null");
    }

    // Format the event message
    String message = event.getMessage();
    if (message == null) {
        throw new IllegalArgumentException("The event message cannot be null");
    }
    message = message.trim();
    if (message.length() == 0) {
        message = "Logging event with blank message.";
    }

    // Format the event time
    Long timestamp = event.getTimestamp();
    if (timestamp == null) {
        throw new IllegalArgumentException("The event timestamp cannot be null");
    }
    String time = DateUtils.formatInstant(timestamp);

    // Format the event level
    String level = event.getLevel().toString().toUpperCase();

    // Format the event thread name
    String threadName = event.getThreadName();
    if (threadName == null) {
        threadName = "Background";
    }

    // Format the event logger
    String logger = event.getLoggerName();
    if (logger == null) {
        logger = "root";
    }

    // Format the event message
    String formattedMessage = "\u001b[1m" + time + " " + level + "[" + threadName + "]" + " " + logger + ": " + message + "\u001b[0m";
    return formattedMessage;
}

public String format(LoggingEvent event) {
    try {
        // Format the date and time of the log event
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        String dateTime = sdf.format(new Date(event.getTimestamp()));

        // Format the log level
        String level;
        switch (event.getLevel().toInt()) {
            case LoggingEvent.TRACE_INT:
                level = "TRACE";
                break;
            case LoggingEvent.DEBUG_INT:
                level = "DEBUG";
                break;
            case LoggingEvent.INFO_INT:
                level = "INFO";
                break;
            case LoggingEvent.WARN_INT:
                level = "WARN";
                break;
            case LoggingEvent.ERROR_INT:
                level = "ERROR";
                break;
            case LoggingEvent.FATAL_INT:
                level = "FATAL";
                break;
            default:
                level = "UNKNOWN";
        }

        // Format the log message
        String message = event.getRenderedMessage();

        // Format the class and method names
        StackTraceElement[] stackTrace = event.getThrowableInformation().getThrowable().getStackTrace();
        String className = stackTrace[1].getClassName();
        String methodName = stackTrace[1].getMethodName();

        // Format the line number
        int lineNumber = stackTrace[1].getLineNumber();

        // Generate the formatted string
        String formattedString = dateTime + " " + level + " " + message + " [" + className + " | " + methodName + " | " + lineNumber + "]";

        // Return the formatted string
        return formattedString;
    } catch (Exception e) {
        e.printStackTrace();
        return null;
    }
}

