public static void abbreviate(final StringBuffer buf, final String name) {
    if (name == null || name.isEmpty()) {
        return;
    }
    final String[] words = name.split(" ");
    if (words.length == 0) {
        return;
    }
    for (int i = 0; i < words.length; i++) {
        if (words[i].length() <= 2) {
            buf.append(words[i]);
        } else {
            buf.append(words[i].charAt(0));
            buf.append(words[i].charAt(words[i].length() - 1));
        }
        if (i < words.length - 1) {
            buf.append('.');
        }
    }
}

