public static List<ThreadSnapshot> loadThreadSnapshotsInTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot threadSnapshot = parseThreadSnapshotFromLine(line);
            if (isWithinRange(threadSnapshot.getTimestamp(), timeRanges)) {
                threadSnapshots.add(threadSnapshot);
            }
        }
    } catch (IOException e) {
        throw new IOException("Error reading from file: " + file, e);
    }

    return threadSnapshots;
}

private static ThreadSnapshot parseThreadSnapshotFromLine(String line) {
    String[] parts = line.split(",");
    return new ThreadSnapshot(
            Long.parseLong(parts[0]),
            Integer.parseInt(parts[1]),
            Integer.parseInt(parts[2]),
            Integer.parseInt(parts[3]),
            Integer.parseInt(parts[4]),
            Integer.parseInt(parts[5])
    );
}

private static boolean isWithinRange(long timestamp, List<ProfileAnalyzeTimeRange> timeRanges) {
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timestamp >= timeRange.startTime && timestamp < timeRange.endTime) {
            return true;
        }
    }
    return false;
