public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        List<String> lines = Files.readAllLines(file.toPath(), StandardCharsets.UTF_8);
        for (String line : lines) {
            if (line.contains(timeRange.getStartTimestamp()) && line.contains(timeRange.getEndTimestamp())) {
                threadSnapshots.add(parseFromLine(line, timeRange));
            }
        }
    }

    return threadSnapshots;
}

private static ThreadSnapshot parseFromLine(String line, ProfileAnalyzeTimeRange timeRange) {
    ThreadSnapshot threadSnapshot = new ThreadSnapshot();
    threadSnapshot.setStartTime(timeRange.getStartTimestamp());
    threadSnapshot.setEndTime(timeRange.getEndTimestamp());
    threadSnapshot.setCpuTime(line.split("\\s+")[11]);
    threadSnapshot.setThreadId(Integer.parseInt(line.split("\\s+")[9]));
    threadSnapshot.setThreadName(line.split("\\s+")[3]);
    return threadSnapshot;
